"""Español — Corán (quran_001 … quran_080)."""

T = {
"quran_001": ("¿Cómo se llama el primer capítulo (sura) del Corán?", ["Al-Fatiha", "Al-Baqara", "Al-Ijlas", "An-Nas"], "Al-Fatiha, «La Apertura», es el primer capítulo del Corán."),
"quran_002": ("¿Cuántos capítulos (suras) tiene el Corán?", ["114", "99", "100", "120"], "El Corán se compone de 114 suras."),
"quran_003": ("¿Cuál es la sura más larga del Corán?", ["Al-Baqara", "Al-Fatiha", "Al-Kawzar", "Al-Asr"], "Al-Baqara es la sura más larga del Corán, con 286 versículos."),
"quran_004": ("¿Cuál es la sura más corta del Corán?", ["Al-Kawzar", "Al-Ijlas", "Al-Asr", "An-Nasr"], "Al-Kawzar, con 3 versículos, es la sura más corta del Corán."),
"quran_005": ("¿En qué lengua fue revelado el Corán?", ["Árabe", "Arameo", "Hebreo", "Persa"], "El Corán afirma explícitamente que fue revelado en lengua árabe."),
"quran_006": ("¿Cómo se llama la sura 19, que lleva el nombre de la madre de Isa?", ["Maryam", "Yusuf", "Al-Kahf", "Ta-Ha"], "La sura 19 del Corán se llama Maryam, por la madre del profeta Isa."),
"quran_007": ("¿Cómo se llama un capítulo del Corán?", ["Una sura", "Un hadiz", "Un yuz'", "Un tafsir"], "El Corán se divide en capítulos llamados suras."),
"quran_008": ("¿Cómo se llama un versículo del Corán?", ["Una aleya", "Una sura", "Un hadiz", "Un ruku'"], "Cada versículo del Corán se llama aleya, que significa «signo»."),
"quran_009": ("¿Qué sura se recita obligatoriamente en cada unidad (rak'a) de la oración?", ["Al-Fatiha", "Al-Ijlas", "Al-Kawzar", "Al-Fil"], "Recitar Al-Fatiha es un pilar de la oración, según un hadiz auténtico."),
"quran_010": ("¿A quién fue revelado el Corán?", ["Al Profeta Muhammad ﷺ", "Al profeta Musa", "Al profeta Isa", "Al profeta Dawud"], "El Corán fue revelado al Profeta Muhammad ﷺ, a través del ángel Yibril."),
"quran_011": ("¿Cómo se llama el famoso versículo 255 de la sura Al-Baqara?", ["Ayat al-Kursi (el Versículo del Trono)", "Ayat an-Nur", "Ayat as-Siyam", "Ayat ad-Dayn"], "El versículo 2:255, Ayat al-Kursi, describe la grandeza de Allah: «Allah, no hay dios sino Él, el Viviente…»."),
"quran_012": ("¿Qué sura no comienza con «Bismillah ir-Rahman ir-Rahim»?", ["At-Tawba", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "At-Tawba (sura 9) es la única sura que no empieza con la basmala."),
"quran_013": ("¿Cuál es el tema del versículo más largo del Corán (2:282)?", ["Poner por escrito las deudas", "La peregrinación", "El ayuno", "La herencia"], "El versículo más largo del Corán enseña a escribir las deudas y tomar testigos: la honestidad queda protegida."),
"quran_014": ("¿Con qué palabra comienzan los primerísimos versículos revelados del Corán?", ["Iqra' (¡Lee!)", "Qul (¡Di!)", "Sabbih (¡Glorifica!)", "Kutiba (Se ha prescrito)"], "Los primeros versículos revelados empiezan con «Iqra'»: «Lee, en el nombre de tu Señor que creó»."),
"quran_015": ("Según el Corán, ¿la Noche de Al-Qadr es mejor que cuántos meses?", ["Mil meses", "Cien meses", "Doce meses", "Cuarenta meses"], "«La Noche de Al-Qadr es mejor que mil meses»: una noche de Ramadán vale más que toda una vida de adoración."),
"quran_016": ("¿Cómo se llaman las dos últimas suras, Al-Falaq y An-Nas, recitadas para buscar protección?", ["Al-Mu'awwidhatan (las dos protectoras)", "Az-Zahrawan", "Al-Mufassal", "As-Sab' at-Tiwal"], "Al-Falaq y An-Nas se llaman «al-mu'awwidhatan»: se recitan para buscar la protección de Allah."),
"quran_017": ("¿En cuántas partes (yuz') se divide tradicionalmente el Corán?", ["30", "10", "60", "114"], "El Corán se divide en 30 yuz', lo que ayuda a completarlo en un mes, por ejemplo en Ramadán."),
"quran_018": ("¿Cuántos versículos tiene la sura Al-Fatiha?", ["7", "3", "10", "14"], "Al-Fatiha tiene siete versículos, recitados en cada unidad de la oración."),
"quran_019": ("¿Qué sura lleva el nombre de un metal?", ["Al-Hadid (El Hierro)", "An-Nur (La Luz)", "Ar-Ra'd (El Trueno)", "Ad-Dujan (El Humo)"], "La sura 57 se llama Al-Hadid: «Hicimos descender el hierro, en el que hay gran fuerza y beneficios para la gente»."),
"quran_020": ("¿Qué relato llama el Corán «el más bello de los relatos»?", ["La historia de Yusuf", "La historia de Nuh", "La historia de la gente de la caverna", "La historia del elefante"], "«Te relatamos el más bello de los relatos»: así comienza la historia de Yusuf."),
"quran_021": ("¿Cuántos versículos tiene Al-Baqara, la sura más larga?", ["286", "114", "200", "365"], "Al-Baqara tiene 286 versículos: la sura más larga del Corán."),
"quran_022": ("¿Qué sura corta proclama: «Di: Él es Allah, Uno»?", ["Al-Ijlas", "Al-Falaq", "An-Nas", "Al-Kawzar"], "Al-Ijlas proclama la perfecta unicidad de Allah en cuatro versículos."),
"quran_023": ("¿A lo largo de cuántos años, aproximadamente, fue revelado el Corán?", ["23 años", "1 año", "10 años", "40 años"], "El Corán fue revelado gradualmente durante unos 23 años, en La Meca y luego en Medina."),
"quran_024": ("Según el Corán, ¿cuál fue la primera Casa establecida para que la gente adorara a Allah?", ["La Ka'ba, en Bakka (La Meca)", "La mezquita de Quba", "Bayt al-Maqdis", "La mezquita del Profeta ﷺ"], "«La primera Casa establecida para la humanidad es la de Bakka, bendita…»: la Ka'ba en La Meca."),
"quran_025": ("¿Qué sura lleva el nombre del elefante?", ["Al-Fil", "An-Nahl", "An-Naml", "Al-Baqara"], "La sura 105, Al-Fil («El Elefante»), recuerda el ejército de elefantes de Abraha, detenido ante La Meca."),
"quran_026": ("¿La sura An-Nahl lleva el nombre de qué insecto?", ["La abeja", "La hormiga", "La araña", "La mosca"], "An-Nahl significa «las abejas»; en ella Allah inspira a la abeja a construir sus casas (16:68)."),
"quran_027": ("¿Qué sura lleva el nombre de la hormiga?", ["An-Naml", "An-Nahl", "Al-Ankabut", "Al-An'am"], "An-Naml («Las Hormigas», sura 27) cuenta la hormiga que avisó a las suyas al acercarse el ejército de Sulayman."),
"quran_028": ("En la sura Al-Ankabut, ¿con qué compara el Corán a quienes toman protectores fuera de Allah?", ["Con la araña que se construye una casa frágil", "Con la abeja que construye su colmena", "Con la hormiga que almacena comida", "Con el perro que jadea"], "«La más frágil de las casas es la casa de la araña» (29:41), de ahí el nombre de la sura."),
"quran_029": ("¿La sura Al-Baqara lleva el nombre de qué animal?", ["La vaca", "El camello", "El caballo", "La oveja"], "Al-Baqara («La Vaca») recuerda la vaca que los Hijos de Israel debían sacrificar (2:67)."),
"quran_030": ("¿Qué significa el título de la sura 6, Al-An'am?", ["Los rebaños", "Los pájaros", "Los jardines", "Las estrellas"], "Al-An'am significa «los rebaños»; la sura refuta las normas inventadas por los paganos sobre el ganado."),
"quran_031": ("¿Qué versículo se repite muchas veces en la sura Ar-Rahman?", ["«¿Cuál de los favores de vuestro Señor negaréis?»", "«Allah es el más Grande»", "«Di: Él es Allah, Uno»", "«Alabado sea Allah»"], "Este estribillo («Fa-bi-ayyi ala'i rabbikuma tukadhdhiban») se repite 31 veces en la sura 55."),
"quran_032": ("Según la sura Al-Kahf, ¿cuánto tiempo durmió la Gente de la Caverna?", ["Trescientos años, y nueve más", "Cien años", "Cuarenta años", "Mil años"], "«Permanecieron en su caverna trescientos años, y añadieron nueve» (18:25)."),
"quran_033": ("¿Qué animal acompañaba a la Gente de la Caverna?", ["Un perro", "Un gato", "Un burro", "Una cabra"], "«Su perro extendía las patas delanteras en la entrada» (18:18)."),
"quran_034": ("¿Contra qué pueblos construyó Dhul-Qarnayn una barrera, según Al-Kahf?", ["Ya'yuy y Ma'yuy (Gog y Magog)", "'Ad y Zamud", "Los romanos", "Los persas"], "Un pueblo le pidió protección contra Ya'yuy y Ma'yuy; levantó una muralla de hierro y cobre (18:94-96)."),
"quran_035": ("¿Qué versículo comienza con «Allah es la Luz de los cielos y de la tierra»?", ["El Versículo de la Luz (An-Nur 24:35)", "El Versículo del Trono", "El Versículo de la Deuda", "El Versículo de la Caverna"], "«Ayat an-Nur» compara Su luz con una hornacina en la que brilla una lámpara (24:35)."),
"quran_036": ("Según un hadiz de al-Bujari, ¿qué sura equivale a un tercio del Corán?", ["Al-Ijlas", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "El Profeta ﷺ dijo de «Qul huwa Allahu ahad» que «equivale a un tercio del Corán»."),
"quran_037": ("¿Qué versículo señaló el Profeta ﷺ como el más grande del Corán, según Sahih Muslim?", ["El Versículo del Trono (Ayat al-Kursi)", "El primer versículo de Al-Fatiha", "El último versículo de Al-Baqara", "El Versículo de la Luz"], "Preguntó a Ubayy ibn Ka'b cuál era el versículo más grande; Ubayy respondió Ayat al-Kursi, y el Profeta ﷺ lo felicitó."),
"quran_038": ("¿Qué enemigo del Profeta ﷺ es nombrado en la sura Al-Masad?", ["Abu Lahab", "Abu Yahl", "Abu Sufyan", "Al-Walid"], "«¡Perezcan las manos de Abu Lahab!» (111:1): este tío del Profeta ﷺ lo combatió abiertamente."),
"quran_039": ("¿Cómo termina la sura Al-Kafirun?", ["«Para vosotros vuestra religión, y para mí mi religión»", "«Allah es el más Grande»", "«Y no hay nadie igual a Él»", "«Del mal del envidioso»"], "«Lakum dinukum wa liya din» (109:6) afirma la clara separación entre el islam y la idolatría."),
"quran_040": ("¿De qué trata la sura An-Nasr?", ["Del auxilio de Allah y de la gente entrando en masa en la religión", "De la creación del cielo", "Del ayuno de Ramadán", "De la historia de Yusuf"], "«Cuando llegue el auxilio de Allah y la victoria, y veas a la gente entrar en masa en la religión de Allah» (110:1-2)."),
"quran_041": ("Según la sura Al-Asr, ¿quién se salva de la pérdida?", ["Los que creen, obran bien y se recomiendan la verdad y la paciencia", "Los ricos", "Los fuertes", "Los que viajan"], "«El hombre está en pérdida, salvo los que creen, obran bien y se recomiendan la verdad y la paciencia» (103:2-3)."),
"quran_042": ("En la sura Al-Ma'un, ¿qué hace «el que niega el Juicio»?", ["Rechaza al huérfano y no anima a alimentar al pobre", "Destruye mezquitas", "Se niega a viajar", "Miente sobre su riqueza"], "«Ese es el que rechaza al huérfano y no anima a alimentar al pobre» (107:2-3)."),
"quran_043": ("Según los primeros versículos revelados (Al-Alaq), ¿de qué creó Allah al hombre?", ["De un coágulo adherente (alaq)", "De luz", "De fuego", "De viento"], "«Lee, en el nombre de tu Señor que creó, que creó al hombre de un coágulo adherente» (96:1-2)."),
"quran_044": ("¿A qué se refiere la expresión coránica «los siete versículos repetidos» (as-sab' al-mazani)?", ["A Al-Fatiha", "A las siete suras más largas", "A Ayat al-Kursi", "A los siete últimos versículos del Corán"], "«Te hemos dado siete de los repetidos y el Corán grandioso» (15:87): Al-Fatiha, recitada en cada rak'a."),
"quran_045": ("¿Qué significa «Al-Furqan», uno de los nombres del Corán?", ["El Criterio (entre verdad y falsedad)", "La Luz", "El Recuerdo", "La Curación"], "«Bendito sea Quien hizo descender el Furqan sobre Su siervo» (25:1): el Libro que separa la verdad de la falsedad."),
"quran_046": ("¿Por qué jura Allah al comienzo de la sura At-Tur?", ["Por el Monte (Tur)", "Por el sol", "Por la higuera", "Por la noche"], "«¡Por el Monte! Y por un Libro escrito…» (52:1-2): el Tur es la montaña donde Musa recibió la revelación."),
"quran_047": ("¿Qué significa «An-Naym», título de la sura 53?", ["La estrella", "La luna", "El sol", "El alba"], "«¡Por la estrella cuando declina!» (53:1)."),
"quran_048": ("Según la sura Al-Qadr, ¿quién desciende en la Noche del Decreto?", ["Los ángeles y el Espíritu (Yibril)", "Los profetas", "Los genios", "Los vientos"], "«Los ángeles y el Espíritu descienden en ella con el permiso de su Señor» (97:4)."),
"quran_049": ("Según el Corán, ¿qué es el Corán para los creyentes?", ["Una curación y una misericordia", "Solo un poema", "Un libro de historia", "Un calendario"], "«Hacemos descender del Corán lo que es curación y misericordia para los creyentes» (17:82)."),
"quran_050": ("¿Qué desafío plantea el Corán a quienes dudan de su origen divino?", ["Producir una sola sura semejante", "Recitar todo el Corán de memoria", "Traducir el Corán", "Construir una mezquita"], "«Si dudáis de lo que hemos revelado, traed una sura semejante» (2:23)."),
"quran_051": ("¿Qué sura se llama «Umm al-Qur'an» (la Madre del Corán)?", ["Al-Fatiha", "Al-Baqara", "Ya-Sin", "Al-Ijlas"], "El Profeta ﷺ dijo: «Umm al-Qur'an son los siete versículos repetidos y el Corán grandioso»."),
"quran_052": ("¿Qué es una sura «mecana» (makkiyya)?", ["Una sura revelada antes de la Hégira", "Una sura revelada en Medina", "Una sura sobre la Ka'ba", "Una sura muy corta"], "Los sabios clasifican las suras según el periodo: antes de la emigración a Medina (mecanas) o después (medinesas)."),
"quran_053": ("¿Cuántas suras comienzan con las letras «Alif, Lam, Mim»?", ["Seis", "Dos", "Diez", "Una"], "Al-Baqara, Al Imran, Al-Ankabut, Ar-Rum, Luqman y As-Sayda comienzan con «Alif, Lam, Mim»."),
"quran_054": ("¿Cómo se llaman las letras aisladas que abren algunas suras (Alif Lam Mim, Ya Sin, Qaf…)?", ["Las letras separadas (al-huruf al-muqatta'a)", "Los versículos abrogados", "Las letras solares", "Las letras del taywid"], "Veintinueve suras comienzan con estas letras, cuyo sentido pleno solo Allah conoce."),
"quran_055": ("¿Qué sura lleva el nombre del Profeta Muhammad ﷺ?", ["La sura 47, Muhammad", "La sura 1, Al-Fatiha", "La sura 36, Ya-Sin", "La sura 112, Al-Ijlas"], "La sura 47 se llama «Muhammad»; menciona su nombre en el versículo 2."),
"quran_056": ("¿Cuál es el primer consejo de Luqman a su hijo, citado en el Corán?", ["No asociar nada a Allah", "Estudiar las estrellas", "Hacerse comerciante", "Viajar lejos"], "«Hijo mío, no asocies nada a Allah; la asociación es una injusticia enorme» (31:13)."),
"quran_057": ("¿Con qué otro nombre se conoce la sura At-Tawba?", ["Bara'a (la Desvinculación)", "An-Nur", "Al-Anfal", "Al-Fath"], "Su primera palabra es «Bara'a»: una declaración de desvinculación de Allah y Su Mensajero respecto a los idólatras (9:1)."),
"quran_058": ("¿Qué sura comienza con las dos letras «Ya, Sin»?", ["Ya-Sin (sura 36)", "Ta-Ha", "Qaf", "Sad"], "La sura 36 comienza con «Ya-Sin. ¡Por el Corán sabio!»."),
"quran_059": ("¿Qué significa «Al-Mulk», título de la sura 67?", ["La Soberanía / el Reino", "La Luz", "El Viaje", "La Victoria"], "«Bendito sea Aquel en cuya mano está la Soberanía (al-Mulk)» (67:1)."),
"quran_060": ("¿Cuál es la última sura del Corán?", ["An-Nas", "Al-Falaq", "Al-Ijlas", "Al-Fatiha"], "An-Nas («Los Hombres»), sura 114, cierra el Corán: «Di: me refugio en el Señor de los hombres»."),
"quran_061": ("¿Cómo comienza la sura Al-Falaq?", ["«Di: me refugio en el Señor del alba»", "«Di: Él es Allah, Uno»", "«¡Por el tiempo!»", "«Alabado sea Allah»"], "«Qul a'udhu bi-rabbi-l-falaq» (113:1): Al-Falaq significa el alba."),
"quran_062": ("¿Qué dos colinas nombra el Corán entre los «ritos de Allah»?", ["As-Safa y Al-Marwa", "Uhud y Zawr", "Arafat y Mina", "Hira y Abu Qubays"], "«As-Safa y Al-Marwa están entre los ritos de Allah» (2:158): entre ellas se hace el sa'y de la peregrinación."),
"quran_063": ("¿Cuál es la única mujer mencionada por su nombre en el Corán?", ["Maryam", "Jadiya", "Asiya", "Hayar"], "Maryam, madre de Isa, es nombrada en varias suras, y una sura entera lleva su nombre."),
"quran_064": ("¿Cuál es el único compañero del Profeta ﷺ nombrado en el Corán?", ["Zayd ibn Hariza", "Abu Bakr", "Umar", "Ali"], "«Cuando Zayd hubo terminado su relación con ella…» (33:37): Zayd, el liberto del Profeta ﷺ, es el único compañero nombrado."),
"quran_065": ("¿Quiénes eran Harut y Marut, mencionados en la sura Al-Baqara?", ["Dos ángeles enviados a Babilonia", "Dos profetas", "Dos reyes de Egipto", "Dos compañeros"], "«…lo que se hizo descender a los dos ángeles Harut y Marut en Babilonia» (2:102): advertían de que la magia era una prueba."),
"quran_066": ("Según el Corán, ¿quién es el más noble ante Allah?", ["El más piadoso", "El más rico", "El más fuerte", "El más famoso"], "«El más noble de vosotros ante Allah es el más piadoso» (49:13)."),
"quran_067": ("¿A qué se refiere «Al-Waqi'a», título de la sura 56?", ["Al Acontecimiento inevitable (el Día de la Resurrección)", "A la caravana", "A la hormiga", "Al viaje nocturno"], "«Cuando suceda el Acontecimiento…» (56:1): la sura describe los tres grupos del Último Día."),
"quran_068": ("¿Por qué objeto jura Allah al comienzo de la sura Al-Qalam?", ["Por el cálamo", "Por la espada", "Por la balanza", "Por la lámpara"], "«Nun. ¡Por el cálamo y lo que escriben!» (68:1)."),
"quran_069": ("¿Cómo comienza la sura Al-Fayr?", ["Con un juramento por el alba y diez noches", "Con un juramento por la higuera", "Con una historia de Yusuf", "Solo con la basmala"], "«¡Por el alba! ¡Y por las diez noches!» (89:1-2)."),
"quran_070": ("¿Por qué astro jura Allah al comienzo de la sura Ash-Shams?", ["Por el sol", "Solo por la luna", "Por las estrellas", "Por los planetas"], "«¡Por el sol y su claridad!» (91:1); Ash-Shams significa «el sol»."),
"quran_071": ("¿Qué sura comienza con: «¿Ha transcurrido para el hombre un periodo de tiempo en que no era nada mencionable?»", ["Al-Insan (sura 76)", "Al-Kahf", "Al-Hayy", "Al-Fatiha"], "Al-Insan («El Hombre»), también llamada Ad-Dahr, recuerda que el hombre no era nada antes de su creación (76:1)."),
"quran_072": ("Según el Corán, ¿para qué ha hecho Allah fácil el Corán?", ["Para el recuerdo y la memorización", "Para el comercio", "Para la traducción", "Para el olvido"], "«Hemos hecho el Corán fácil de recordar; ¿hay quien reflexione?» (54:17), repetido cuatro veces en la sura."),
"quran_073": ("¿Qué signo menciona la sura Al-Qamar en su primer versículo?", ["La luna se partió", "El sol se apagó", "El mar se abrió", "La montaña habló"], "«La Hora se acerca y la luna se ha partido» (54:1): un signo mostrado a los mecanos."),
"quran_074": ("¿Por qué fue revelado el Corán gradualmente y no de una vez, según el propio Corán?", ["Para afianzar el corazón del Profeta ﷺ", "Porque era demasiado largo", "Para ocultarlo de los enemigos", "Por los viajes"], "«Así, para afianzar con él tu corazón, y lo hemos recitado con esmero» (25:32)."),
"quran_075": ("¿Qué suras recitaba el Profeta ﷺ cada noche en sus manos antes de dormir, según Aisha?", ["Al-Ijlas, Al-Falaq y An-Nas", "Al-Fatiha y Al-Baqara", "Ya-Sin y Al-Mulk", "Al-Kahf y Maryam"], "Soplaba en sus manos recitando las tres suras «Qul», y luego se las pasaba por el cuerpo, tres veces."),
"quran_076": ("¿Cómo se llama la postración que se hace al recitar ciertos versículos del Corán?", ["La postración de recitación (suyud at-tilawa)", "La postración del olvido", "La postración de agradecimiento", "El ruku'"], "El Corán contiene versículos de postración, como el último de Al-Alaq: «póstrate y acércate» (96:19)."),
"quran_077": ("¿Cómo se llama la ciencia de las reglas de la correcta pronunciación del Corán?", ["El taywid", "El tafsir", "El fiqh", "La sira"], "El taywid enseña a pronunciar cada letra desde su punto de articulación, con sus cualidades."),
"quran_078": ("¿Cómo se llama a la persona que ha memorizado todo el Corán?", ["Un hafiz", "Un imam", "Un almuédano", "Un muftí"], "Hafiz significa «el que guarda»: lleva el Corán entero en su memoria."),
"quran_079": ("¿Cómo se llama el ejemplar escrito del Corán?", ["Un mushaf", "Un hadiz", "Un yuz'", "Un minbar"], "El mushaf es el Corán reunido entre dos tapas; un yuz' es una de sus treinta partes."),
"quran_080": ("¿En qué sura aparece la basmala dos veces?", ["An-Naml", "Al-Fatiha", "At-Tawba", "Al-Baqara"], "Además de su inicio, An-Naml cita la basmala al comienzo de la carta de Sulayman a la reina de Saba (27:30)."),
}
